// Verifies the HMAC signature LendLoop (Convex) puts on every event: see convex/lib/hmac.ts.
//   X-LendLoop-Timestamp: unix seconds   X-LendLoop-Signature: v1=hex(HMAC-SHA256(secret, timestamp + "." + rawBody))
// The secret comes from the environment (LENDLOOP_TO_N8N_SECRET), never from this workflow.
const { createHmac, timingSafeEqual } = require('crypto');
const TOLERANCE_SECONDS = 300;

const secret = $env.LENDLOOP_TO_N8N_SECRET;
const headers = $input.first().json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');

// The exact bytes that were signed (the Webhook node's "Raw Body" option), not a re-serialized copy.
let raw = '';
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (error) {
  raw = '';
}

let reason = '';
if (!secret) reason = 'LENDLOOP_TO_N8N_SECRET is not set';
else if (!/^\d{1,12}$/.test(timestamp) || !signature) reason = 'missing signature headers';
else if (Math.abs(Date.now() / 1000 - Number(timestamp)) > TOLERANCE_SECONDS) reason = 'stale timestamp';
else {
  const expected = Buffer.from('v1=' + createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex'));
  const given = Buffer.from(signature);
  if (expected.length !== given.length || !timingSafeEqual(expected, given)) reason = 'bad signature';
}

if (reason) return [{ json: { valid: false, reason } }];
// Only the verified event goes on; the request headers stay here.
return [{ json: { valid: true, event: JSON.parse(raw) } }];

// Turns a verified LendLoop event into an email. Uses only what the email needs.
const e = $json.event;
const day = (iso) => new Date(iso + 'T00:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
const dates = day(e.loan.startDate) + ' – ' + day(e.loan.endDate);
const other = e.otherParty.name;
const tool = e.tool.name;

const messages = {
  'loan.requested': [other + ' wants to borrow your ' + tool,
    other + ' asked to borrow your ' + tool + ' for ' + dates + '. Approve or decline it in LendLoop, under "Incoming requests".'],
  'loan.approved': [other + ' approved your request for the ' + tool,
    'Good news: you can borrow the ' + tool + ' for ' + dates + '. Arrange the pickup with ' + other + '.'],
  'loan.declined': ['Your request for the ' + tool + ' was declined',
    'Your request to borrow the ' + tool + ' for ' + dates + ' was declined. Other neighbors may have one: have a look in LendLoop.'],
  'loan.cancelled': e.recipient.role === 'owner'
    ? [other + ' cancelled their request for your ' + tool, other + ' no longer needs your ' + tool + ' for ' + dates + '.']
    : ['Your loan of the ' + tool + ' was cancelled', 'The ' + tool + ' is no longer available for ' + dates + ': the listing was removed.'],
  'loan.returned': ['Thanks for returning the ' + tool, other + ' confirmed that the ' + tool + ' is back. Thanks for looking after it!'],
};
const [subject, body] = messages[e.type] || ['Update on your LendLoop loan', 'There is an update on the ' + tool + ' (' + dates + ').'];

return {
  json: {
    eventId: e.eventId,
    to: e.recipient.email,
    subject,
    text: 'Hi ' + e.recipient.name + ',\n\n' + body + '\n\n– LendLoop',
  },
};

// Reports the outcome back to LendLoop, signed with N8N_TO_LENDLOOP_SECRET (same scheme as above).
// This node gets both outputs of "Send email": items with an "error" field come from the error output.
const { createHmac } = require('crypto');
const eventId = $('Build email').item.json.eventId;
const failed = Boolean($json.error);
const report = { eventId, status: failed ? 'failed' : 'sent' };
if (failed) report.error = String(($json.error && $json.error.message) || $json.error).slice(0, 300);

const body = JSON.stringify(report);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'v1=' + createHmac('sha256', $env.N8N_TO_LENDLOOP_SECRET).update(timestamp + '.' + body).digest('hex');
return {
  json: {
    body,
    headers: { 'Content-Type': 'application/json', 'X-LendLoop-Timestamp': timestamp, 'X-LendLoop-Signature': signature },
  },
};
